package com.lebzlon.measurementtracker.config; import com.lebzlon.measurementtracker.security.JwtAuthFilter; import org.springframework.context.annotation.*; import org.springframework.security.authentication.*; import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import com.lebzlon.measurementtracker.repository.UserRepository;
@Configuration public class SecurityConfig { @Bean UserDetailsService uds(UserRepository repo){ return u->repo.findByUsername(u).map(x->User.withUsername(x.getUsername()).password(x.getPassword()).authorities("USER").build()).orElseThrow(()->new UsernameNotFoundException("Not found")); } @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean AuthenticationManager am(AuthenticationConfiguration c) throws Exception {return c.getAuthenticationManager();} @Bean SecurityFilterChain chain(HttpSecurity http, JwtAuthFilter f) throws Exception {http.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/auth/**","/swagger-ui/**","/v3/api-docs/**","/","/login","/register","/dashboard","/css/**").permitAll().anyRequest().authenticated()).addFilterBefore(f, UsernamePasswordAuthenticationFilter.class); return http.build();}}
